/**
 * Server-side access to the API model (`model.json`, generated by `scripts/api-model.js`) and its rendering to HTML.
 * Used by the `+page.server.js` / `+layout.server.js` loads of src/routes/(site)/api: they run at build time (prerender).
 */
import model from './model.json';
import { getHighlighter, highlightSync } from '../docs/highlight.server.js';
import { createMarkdown } from '../docs/markdown.server.js';

/** @typedef {typeof model} ApiModel */

export const getModel = () => model;

export const KIND_ORDER = ['function', 'class', 'component', 'constant', 'type'];
export const KIND_TITLE = /** @type {Record<string, string>} */ ({ function: 'Function', class: 'Class', component: 'Component', constant: 'Constant', type: 'Type' });

/** Every `[entry, name]` that has a page: what `entries()` hands to the prerenderer. */
export const allPages = () => Object.values(model.items).map((i) => ({ entry: i.entry, name: i.name }));

/** Navigation of the API section (left column), shared by every API page. */
export function navSections() {
  return model.entries.map((entry) => ({
    id: entry.id,
    title: entry.specifier,
    href: `/api#entry-${entry.id}`,
    groups: entry.groups.map((g) => ({
      title: g.title,
      items: g.items.map((name) => ({ label: name, href: `/api/${entry.id}/${name}` })),
    })),
  }));
}

/** identifier -> href of the documented types / classes, for the links inside signatures (root wins on a duplicate). */
function linkMap() {
  const links = new Map();
  for (const e of model.entries) {
    for (const g of e.groups) for (const name of g.items) if (!links.has(name)) links.set(name, `/api/${e.id}/${name}`);
  }
  return links;
}

const isHtmlKey = new Set(['summary', 'description', 'returns', 'deprecated']);

/**
 * Deep copy of an item with the Markdown rendered (`summaryHtml`...) and the code highlighted (`codeHtml`).
 * @param {any} item
 */
export async function renderItem(item) {
  const h = await getHighlighter();
  const links = linkMap();
  const md = createMarkdown(h, { links, self: item.name });
  const lang = item.kind === 'component' ? 'svelte' : 'ts';
  const hl = (/** @type {string} */ code, l = lang) => highlightSync(h, code, l, { links, self: item.name });
  /**
   * @param {any} node
   * @returns {any}
   */
  function walk(node) {
    if (Array.isArray(node)) return node.map(walk);
    if (!node || typeof node !== 'object') return node;
    const out = /** @type {Record<string, any>} */ ({});
    for (const [key, value] of Object.entries(node)) {
      if (key === 'type' && Array.isArray(value)) { out[key] = value; continue; } // type parts are data, not nodes to render
      if (isHtmlKey.has(key) && typeof value === 'string') { out[key + 'Html'] = value ? md.block(value) : ''; out[key] = value; continue; }
      if (key === 'examples') { out.examplesHtml = value.map((/** @type {string} */ ex) => md.block(ex)); continue; }
      if (key === 'see') { out.seeHtml = value.map((/** @type {string} */ s) => md.inline(s)); continue; }
      if (key === 'code' && typeof value === 'string') { out.codeHtml = hl(value); continue; }
      if (key === 'usage' || key === 'value') { out[key] = value; continue; }
      out[key] = walk(value);
    }
    return out;
  }
  return { item: walk(item), md, hl };
}

/** One-line description of an export (index and nav): the first paragraph, inline Markdown. */
/** @param {string} markdown */
export async function inlineSummary(markdown) {
  const h = await getHighlighter();
  return createMarkdown(h).inline(markdown);
}

function inheritedBy(/** @type {any[]} */ members) {
  /** @type {Map<string, any>} */
  const owners = new Map();
  for (const m of members) {
    if (!m.inheritedFrom) continue;
    const target = Object.values(model.items).find((i) => i.name === m.inheritedFrom && i.kind === 'class');
    const entry = owners.get(m.inheritedFrom) ?? { owner: m.inheritedFrom, href: target ? `/api/${target.id}` : '', members: [] };
    entry.members.push({ name: m.name, id: m.id });
    owners.set(m.inheritedFrom, entry);
  }
  return [...owners.values()];
}

/** Members of a class split in the groups the page shows. */
export function groupMembers(/** @type {any} */ item) {
  const own = (/** @type {any[]} */ list) => list.filter((m) => !m.inheritedFrom);
  const members = item.members ?? [];
  return {
    statics: own(members.filter((/** @type {any} */ m) => m.static)),
    properties: own(members.filter((/** @type {any} */ m) => !m.static && m.kind === 'property')),
    methods: own(members.filter((/** @type {any} */ m) => !m.static && m.kind === 'method')),
    inherited: members.filter((/** @type {any} */ m) => m.inheritedFrom),
    /** @type {Array<{ owner: string, href: string, members: Array<{ name: string, id: string }> }>} */
    inheritedBy: inheritedBy(members),
  };
}

/** "On this page" entries of an item page: must match the section ids drawn by src/site/api/ItemView.svelte. */
export function tocFor(/** @type {any} */ item) {
  /** @type {Array<{ id: string, label: string, level: 1 | 2 }>} */
  const toc = [];
  const add = (/** @type {string} */ id, /** @type {string} */ label, level = /** @type {1 | 2} */ (1)) => toc.push({ id, label, level });
  if (item.kind === 'function') {
    add('signature', 'Signature');
    if (item.signatures.some((/** @type {any} */ s) => s.params.length)) add('parameters', 'Parameters');
    if (item.signatures.some((/** @type {any} */ s) => s.returnsHtml || s.returnType)) add('returns', 'Returns');
  } else if (item.kind === 'class') {
    add('import', 'Import');
    if (item.constructors?.length) add('constructor', 'Constructor');
    const g = groupMembers(item);
    for (const [id, label, list] of /** @type {const} */ ([['static-members', 'Static members', g.statics], ['properties', 'Properties', g.properties], ['methods', 'Methods', g.methods]])) {
      if (!list.length) continue;
      add(id, label);
      for (const m of list) add(m.id, m.name + (m.kind === 'method' ? '()' : ''), 2);
    }
    if (g.inherited.length) add('inherited', 'Inherited');
  } else if (item.kind === 'type') {
    add('definition', 'Definition');
    if (item.properties?.length) add('properties', 'Properties');
  } else if (item.kind === 'constant') {
    add('declaration', 'Declaration');
    if (item.properties?.length) add('properties', 'Properties');
  } else if (item.kind === 'component') {
    add('usage', 'Usage');
    if (item.props?.length) add('props', 'Props');
  }
  if (item.examplesHtml?.length) add('examples', 'Examples');
  return toc;
}
